(function () {
  "use strict";

  const reportDataUrl = "data:image/png;base64,";
  let reportBuffer = null;

  function reportArrayBuffer() {
    if (reportBuffer) return reportBuffer.slice(0);
    const binary = window.atob(reportDataUrl.split(",")[1]);
    const bytes = new Uint8Array(binary.length);
    for (let index = 0; index < binary.length; index += 1) bytes[index] = binary.charCodeAt(index);
    reportBuffer = bytes.buffer;
    return reportBuffer.slice(0);
  }

  function addReportLogo(workbook) {
    return workbook.addImage({ base64: reportDataUrl, extension: "png" });
  }

  window.RECONBrand = Object.freeze({
    appLogo: "recon-logo-app.png",
    icon: "recon-icon.png",
    reportLogo: "recon-logo-report.png",
    reportDataUrl,
    reportArrayBuffer,
    addReportLogo,
  });
})();
